content:
.desktop-window-toolbar{display:flex;flex-wrap:wrap;gap:4px;padding:4px 6px;align-items:center;min-height:30px;border-bottom:1px solid var(--border)}
.desktop-window-toolbar>span{font-size:11px;color:var(--muted)}.desktop-window-toolbar input{flex:1;min-width:80px}
.desktop-icon-button{width:26px;height:25px;padding:4px!important;display:inline-flex;align-items:center;justify-content:center}.desktop-icon-button svg{width:15px;height:15px}
.dock-right-stack{display:grid;grid-template-rows:minmax(0,1fr);min-height:0;min-width:0;overflow:hidden}
.dock-right-stack[data-split=true]{grid-template-rows:minmax(0,var(--dock-rightRatio,48%)) 5px minmax(0,1fr)}
.dock-bottom-stack{grid-row:3;display:grid;grid-template-columns:minmax(0,1fr);min-width:0;min-height:0;overflow:hidden}
.dock-bottom-stack[data-split=true]{grid-template-columns:minmax(0,var(--dock-bottomRatio,52%)) 5px minmax(0,1fr)}
.desktop-splitter{background:var(--bg);touch-action:none;position:relative;min-width:0;min-height:0;z-index:5;outline:none;border:0;flex:none}
.desktop-splitter.vertical{width:5px;cursor:col-resize}.desktop-splitter.horizontal{height:5px;cursor:row-resize}.desktop-splitter:hover,.desktop-splitter:focus-visible{background:var(--accent)}
.desktop-main>.desktop-splitter{grid-row:2}.desktop-splitter[data-resize=split]{align-self:stretch}
.dock-auto-rail{display:flex;flex-direction:column;align-items:stretch;gap:5px;background:var(--panel2);padding:5px 1px;min-width:0;overflow:hidden}
.dock-auto-tab{writing-mode:vertical-rl;display:flex;align-items:center;gap:7px;font-size:11px;border-radius:0!important;padding:9px 5px!important;border-left:2px solid var(--line);color:var(--muted)}.dock-auto-tab[aria-expanded=true]{border-left-color:var(--accent);background:var(--selection);color:var(--text)}
.dock-flyout{position:absolute;z-index:44;top:0;bottom:0;width:min(360px,90vw);display:grid;grid-template-rows:26px minmax(0,1fr);border:1px solid var(--accent);box-shadow:5px 3px 18px #0006;background:var(--panel)}
.dock-flyout.left{left:27px}.dock-flyout.right{right:27px}.dock-flyout>.desktop-tool-view{height:100%}

.dock-floating{position:fixed;z-index:45;display:grid;grid-template-rows:27px minmax(0,1fr);border:1px solid var(--accent);background:var(--panel);box-shadow:0 12px 42px #0008;min-width:0;min-height:0}
.dock-float-resize{position:absolute;width:15px;height:15px;right:0;bottom:0;cursor:nwse-resize;background:linear-gradient(135deg,transparent 60%,var(--line) 62%,transparent 68%,var(--line) 72%);touch-action:none}
#dock-drop-overlay{position:absolute;inset:0;z-index:100;pointer-events:none;background:#0001}.dock-drop-target{position:absolute;pointer-events:auto;min-width:82px;min-height:43px;background:var(--panel2)!important;border:2px solid var(--accent);font-size:11px;box-shadow:0 4px 18px #0007}
.dock-drop-target.left{left:30px;top:40%}.dock-drop-target.right{right:35px;top:25%}.dock-drop-target.right-lower{right:35px;top:65%}.dock-drop-target.bottom{left:40%;bottom:25px}.dock-drop-target.bottom-right{left:60%;bottom:25px}.dock-drop-target.active,.dock-drop-hover{outline:3px solid var(--accent);background:var(--selection)!important}
.dock-dragging iframe,.wb-resizing iframe{pointer-events:none!important}.dock-dragging{cursor:grabbing!important;user-select:none}
.desktop-ide .desktop-build-status{height:23px;min-height:23px;display:flex;align-items:center;gap:12px;padding:0 9px;background:var(--panel);border-top:1px solid var(--border);font-size:10px;overflow:hidden}
.desktop-build-status #build-summary{margin:0;flex:none;font-size:10px}.desktop-build-status #dev-status{padding:0;min-height:0;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--muted)}.desktop-build-status .live-label{margin-left:auto;flex:none;font-size:10px}
.desktop-ide .statusbar{height:22px;min-height:22px;background:#493461;font-size:10px}.desktop-ide.light .statusbar{color:#fff}.desktop-ide .status-right{font-size:9px}
